/** Strapi DTO types — mirror cms/src/api/country (see contracts/countries-api.md). */
export interface CountryIconDto {
  id: number;
  documentId: string;
  url: string;
  alternativeText: string | null;
}

export interface CountryDto {
  id: number;
  documentId: string;
  name: string;
  code: string;
  icon: CountryIconDto | null;
}

export interface CountriesResponseDto {
  data: CountryDto[];
  meta?: { pagination?: { page: number; pageSize: number; pageCount: number; total: number } };
}

/** App model. `code` is lower case (e.g. 'co'). */
export interface Country {
  code: string;
  name: string;
  iconUrl: string | null;
  iconAlt: string;
}

import { Country, CountryDto } from './country.model';

export function mapCountry(dto: CountryDto): Country {
  return {
    code: dto.code.toLowerCase(),
    name: dto.name,
    iconUrl: dto.icon?.url ?? null,
    iconAlt: dto.icon?.alternativeText || dto.name,
  };
}

export function mapCountries(dtos: CountryDto[]): Country[] {
  return dtos.map(mapCountry);
}

import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map, shareReplay } from 'rxjs';
import { mapCountries } from './country.mapper';
import { CountriesResponseDto, Country } from './country.model';

export function findCountryByCode(countries: Country[], code: string): Country | undefined {
  const wanted = code.toLowerCase();
  return countries.find((country) => country.code === wanted);
}

@Injectable({ providedIn: 'root' })
export class CountryService {
  private readonly http = inject(HttpClient);
  private cached$: Observable<Country[]> | null = null;

  /** Shared request: guard and page reuse the same result. Failures are not cached. */
  load(): Observable<Country[]> {
    if (!this.cached$) {
      const params = new HttpParams()
        .set('fields[0]', 'name')
        .set('fields[1]', 'code')
        .set('populate[icon][fields][0]', 'url')
        .set('populate[icon][fields][1]', 'alternativeText')
        .set('sort', 'order:asc');
      const request$ = this.http.get<CountriesResponseDto>('/api/countries', { params }).pipe(
        map((response) => mapCountries(response.data)),
        shareReplay({ bufferSize: 1, refCount: false }),
      );
      this.cached$ = request$;
      // Drop the cache on failure so a retry issues a new request.
      request$.subscribe({
        error: () => {
          if (this.cached$ === request$) this.cached$ = null;
        },
      });
    }
    return this.cached$;
  }

  /** Forces a fresh request (e.g. "Reintentar"). */
  reload(): Observable<Country[]> {
    this.cached$ = null;
    return this.load();
  }

  findByCode(countries: Country[], code: string): Country | undefined {
    return findCountryByCode(countries, code);
  }
}

import { mapCountry } from './country.mapper';
import { CountryDto } from './country.model';
import { findCountryByCode } from './country.service';

const base: CountryDto = { id: 1, documentId: 'a', name: 'Colombia', code: 'CO', icon: null };

describe('US-00 · FR-001 country mapper', () => {
  it('lower-cases the code', () => {
    expect(mapCountry(base).code).toBe('co');
  });

  it('maps icon url and alternative text', () => {
    const country = mapCountry({
      ...base,
      icon: { id: 1, documentId: 'x', url: '/uploads/co.svg', alternativeText: 'Bandera de Colombia' },
    });
    expect(country.iconUrl).toBe('/uploads/co.svg');
    expect(country.iconAlt).toBe('Bandera de Colombia');
  });

  it('returns null iconUrl and name as alt when there is no icon', () => {
    const country = mapCountry(base);
    expect(country.iconUrl).toBeNull();
    expect(country.iconAlt).toBe('Colombia');
  });

  it('falls back to the name when alternativeText is null', () => {
    const country = mapCountry({
      ...base,
      icon: { id: 1, documentId: 'x', url: '/u.svg', alternativeText: null },
    });
    expect(country.iconAlt).toBe('Colombia');
  });
});

describe('US-00 · FR-001 findByCode', () => {
  const countries = [mapCountry(base), mapCountry({ ...base, id: 2, name: 'Chile', code: 'CL' })];

  it('finds case-insensitively', () => {
    expect(findCountryByCode(countries, 'CL')?.name).toBe('Chile');
    expect(findCountryByCode(countries, 'co')?.name).toBe('Colombia');
  });

  it('returns undefined for unknown codes', () => {
    expect(findCountryByCode(countries, 'xx')).toBeUndefined();
  });
});

import { Injectable } from '@angular/core';

export const QUOTE_SESSION_KEY = 'quote-session';

export interface QuoteSession {
  countryCode: string;
  data: Record<string, unknown>;
}

/** Single persistence helper for the quote wizard (sessionStorage). Never stores tokens. */
@Injectable({ providedIn: 'root' })
export class QuoteSessionStore {
  read(): QuoteSession | null {
    try {
      const raw = sessionStorage.getItem(QUOTE_SESSION_KEY);
      if (!raw) return null;
      const parsed: unknown = JSON.parse(raw);
      if (typeof parsed !== 'object' || parsed === null) return null;
      const { countryCode, data } = parsed as Partial<QuoteSession>;
      if (typeof countryCode !== 'string' || !countryCode) return null;
      const safeData =
        typeof data === 'object' && data !== null && !Array.isArray(data) ? data : {};
      return { countryCode, data: safeData };
    } catch {
      return null;
    }
  }

  lastCountryCode(): string | null {
    return this.read()?.countryCode ?? null;
  }

  hasData(): boolean {
    const session = this.read();
    return session !== null && Object.keys(session.data).length > 0;
  }

  /** Same country keeps data; a different country resets it. */
  start(countryCode: string): void {
    const current = this.read();
    const data = current?.countryCode === countryCode ? current.data : {};
    this.write({ countryCode, data });
  }

  /** Keeps the country, empties the form data. */
  discardData(): void {
    const current = this.read();
    if (current) this.write({ countryCode: current.countryCode, data: {} });
  }

  clear(): void {
    try {
      sessionStorage.removeItem(QUOTE_SESSION_KEY);
    } catch {
      /* storage unavailable */
    }
  }

  private write(session: QuoteSession): void {
    try {
      sessionStorage.setItem(QUOTE_SESSION_KEY, JSON.stringify(session));
    } catch {
      /* storage unavailable: degrade to no persistence */
    }
  }
}

import { QUOTE_SESSION_KEY, QuoteSessionStore } from './quote-session.store';

function seed(value: unknown): void {
  sessionStorage.setItem(QUOTE_SESSION_KEY, JSON.stringify(value));
}

describe('US-00 · FR-011 / FR-012 quote session store', () => {
  let store: QuoteSessionStore;

  beforeEach(() => {
    sessionStorage.clear();
    store = new QuoteSessionStore();
  });

  it('returns null when nothing is stored', () => {
    expect(store.read()).toBeNull();
    expect(store.lastCountryCode()).toBeNull();
    expect(store.hasData()).toBe(false);
  });

  it('treats corrupt JSON as no session', () => {
    sessionStorage.setItem(QUOTE_SESSION_KEY, '{not json');
    expect(store.read()).toBeNull();
    expect(store.hasData()).toBe(false);
  });

  it('treats a malformed shape as no session', () => {
    seed({ data: {} });
    expect(store.read()).toBeNull();
  });

  it('start creates a session with empty data', () => {
    store.start('co');
    expect(store.read()).toEqual({ countryCode: 'co', data: {} });
    expect(store.lastCountryCode()).toBe('co');
  });

  it('hasData is true only when data has at least one key', () => {
    seed({ countryCode: 'co', data: {} });
    expect(store.hasData()).toBe(false);
    seed({ countryCode: 'co', data: { plate: 'ABC123' } });
    expect(store.hasData()).toBe(true);
  });

  it('start with the same country keeps the data (FR-011)', () => {
    seed({ countryCode: 'co', data: { plate: 'ABC123' } });
    store.start('co');
    expect(store.read()?.data).toEqual({ plate: 'ABC123' });
  });

  it('start with a different country resets the data (FR-012)', () => {
    seed({ countryCode: 'co', data: { plate: 'ABC123' } });
    store.start('cl');
    expect(store.read()).toEqual({ countryCode: 'cl', data: {} });
  });

  it('discardData keeps the country and empties data', () => {
    seed({ countryCode: 'co', data: { plate: 'ABC123' } });
    store.discardData();
    expect(store.read()).toEqual({ countryCode: 'co', data: {} });
  });

  it('clear removes the session', () => {
    seed({ countryCode: 'co', data: { a: 1 } });
    store.clear();
    expect(store.read()).toBeNull();
  });
});

import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  afterNextRender,
  input,
  output,
  viewChild,
} from '@angular/core';

export interface ConfirmOptions {
  title: string;
  message: string;
  confirmLabel: string;
  cancelLabel: string;
}

@Component({
  selector: 'app-confirm-dialog',
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './confirm-dialog.component.scss',
  template: `
    <dialog
      #dialog
      class="confirm-dialog"
      aria-labelledby="confirm-dialog-title"
      aria-describedby="confirm-dialog-message"
      (cancel)="onCancel($event)"
      (click)="onBackdropClick($event)"
    >
      <div class="confirm-dialog__content">
        <h2 id="confirm-dialog-title" class="confirm-dialog__title">{{ options().title }}</h2>
        <p id="confirm-dialog-message" class="confirm-dialog__message">{{ options().message }}</p>
        <div class="confirm-dialog__actions">
          <button type="button" class="button button--secondary" (click)="closed.emit(false)">
            {{ options().cancelLabel }}
          </button>
          <button type="button" class="button button--primary" (click)="closed.emit(true)">
            {{ options().confirmLabel }}
          </button>
        </div>
      </div>
    </dialog>
  `,
})
export class ConfirmDialogComponent {
  readonly options = input.required<ConfirmOptions>();
  readonly closed = output<boolean>();

  private readonly dialog = viewChild.required<ElementRef<HTMLDialogElement>>('dialog');

  constructor() {
    afterNextRender(() => this.dialog().nativeElement.showModal());
  }

  protected onCancel(event: Event): void {
    event.preventDefault();
    this.closed.emit(false);
  }

  protected onBackdropClick(event: MouseEvent): void {
    if (event.target === this.dialog().nativeElement) this.closed.emit(false);
  }
}

